@TestOn('vm')
library;

import 'dart:convert';
import 'dart:io';

import 'package:path/path.dart' as p;
import 'package:skills_sync/skills_sync.dart';
import 'package:test/test.dart';

const _ships = <String, List<String>>{
  'a': ['b'],
  'b': <String>[],
};

final Matcher _throwsSkillsSyncException = throwsA(isA<SkillsSyncException>());

const _generatedHeader =
    '# Generated by tool/skills_sync. Do not edit; run melos run skills:sync.';

/// Maps each path under [dir] to its modification time and content, so a test
/// sees any create, delete, or write.
Map<String, String> snapshot(Directory dir) => {
  '.': '${dir.statSync().modified.microsecondsSinceEpoch}',
  for (final entity in dir.listSync(recursive: true, followLinks: false))
    p.relative(entity.path, from: dir.path):
        '${entity.statSync().modified.microsecondsSinceEpoch} '
        '${entity is File ? entity.readAsStringSync() : ''}',
};

void main() {
  late Directory repo;

  String path(String relative) => p.joinAll([repo.path, ...p.split(relative)]);

  File file(String relative) => File(path(relative));

  void write(String relative, String content) => file(relative)
    ..createSync(recursive: true)
    ..writeAsStringSync(content);

  String skillMd(String name) =>
      '---\nname: $name\ndescription: d\n---\nbody\n';

  void writeConfig(Map<String, String> rootUris) => write(
    '.dart_tool/package_config.json',
    jsonEncode({
      'configVersion': 2,
      'packages': [
        for (final entry in rootUris.entries)
          {'name': entry.key, 'rootUri': entry.value, 'packageUri': 'lib/'},
      ],
    }),
  );

  setUp(() {
    repo = Directory.systemTemp.createTempSync('skills_sync_run_');
    writeConfig({for (final name in _ships.keys) name: '../$name'});
    write('b/skills/b-x/SKILL.md', skillMd('b-x'));
    write('b/skills/b-x/references/r.md', 'ref\n');
  });

  tearDown(() => repo.deleteSync(recursive: true));

  Future<List<String>> check() => runCheck(repo.path, ships: _ships);

  Future<List<String>> sync() => runSync(repo.path, ships: _ships);

  /// Creates a package outside the repository, as the pub cache would hold it.
  Directory externalPackage() {
    final dir = Directory.systemTemp.createTempSync('skills_sync_ext_');
    addTearDown(() {
      if (dir.existsSync()) dir.deleteSync(recursive: true);
    });
    return dir;
  }

  void writeIn(Directory dir, String relative, String content) =>
      File(p.joinAll([dir.path, ...p.split(relative)]))
        ..createSync(recursive: true)
        ..writeAsStringSync(content);

  test('resolvePackageRoots reads roots from the package config', () async {
    expect(await resolvePackageRoots(repo.path, ['a', 'b']), {
      'a': path('a'),
      'b': path('b'),
    });
  });

  test('sync writes copy and GENERATED', () async {
    final written = await sync();

    expect(written, [path('a/skills/a-b-x')]);
    expect(
      file('a/skills/a-b-x/SKILL.md').readAsStringSync(),
      contains('name: a-b-x'),
    );
    expect(file('a/skills/a-b-x/references/r.md').readAsStringSync(), 'ref\n');
    expect(
      file('a/skills/GENERATED').readAsStringSync(),
      '$_generatedHeader\na-b-x\n',
    );
    expect(file('b/skills/GENERATED').existsSync(), isFalse);
    expect(await check(), isEmpty);
  });

  test('sync drops GENERATED from a package without copies', () async {
    write('b/skills/GENERATED', '$_generatedHeader\n');

    await sync();

    expect(file('b/skills/GENERATED').existsSync(), isFalse);
  });

  test('check reports a missing copy', () async {
    expect(await check(), contains(contains(path('a/skills/a-b-x'))));
  });

  test('check reports hand edit', () async {
    await sync();
    file('a/skills/a-b-x/references/r.md')
        .writeAsStringSync('more\n', mode: FileMode.append);

    expect(await check(), [contains(path('a/skills/a-b-x/references/r.md'))]);
  });

  test('check reports orphan and sync removes it', () async {
    await sync();
    write('a/skills/a-old/SKILL.md', skillMd('a-old'));
    file('a/skills/GENERATED')
        .writeAsStringSync('a-old\n', mode: FileMode.append);

    expect(await check(), [contains(path('a/skills/a-old'))]);

    await sync();

    expect(Directory(path('a/skills/a-old')).existsSync(), isFalse);
    expect(await check(), isEmpty);
  });

  test('sync refuses to overwrite a hand-written skill', () async {
    write('a/skills/a-b-x/SKILL.md', skillMd('a-b-x'));
    write('a/skills/a-b-x/mine.md', 'mine\n');

    await expectLater(sync, _throwsSkillsSyncException);

    expect(file('a/skills/a-b-x/mine.md').readAsStringSync(), 'mine\n');
    expect(file('a/skills/a-b-x/references/r.md').existsSync(), isFalse);
    expect(file('a/skills/GENERATED').existsSync(), isFalse);
  });

  test('check throws on a copy name held by an unlisted skill', () async {
    await sync();
    write('a/skills/GENERATED', '$_generatedHeader\n');

    expect(check, _throwsSkillsSyncException);
  });

  test('sync validates every source before it deletes anything', () async {
    await sync();
    write('b/skills/b-x/SKILL.md', '---\ndescription: d\n---\nbody\n');

    await expectLater(
      sync,
      throwsA(
        isA<SkillsSyncException>().having(
          (error) => error.message,
          'message',
          contains(path('b/skills/b-x/SKILL.md')),
        ),
      ),
    );

    expect(file('a/skills/a-b-x/references/r.md').existsSync(), isTrue);
    expect(
      file('a/skills/GENERATED').readAsStringSync(),
      '$_generatedHeader\na-b-x\n',
    );
  });

  test('sync recovers after an interrupted run', () async {
    write('b/skills/b-y/SKILL.md', skillMd('b-y'));
    write('a/skills/a-b-y', 'blocks the second copy');

    await expectLater(sync, throwsA(isA<FileSystemException>()));

    expect(
      file('a/skills/GENERATED').readAsStringSync(),
      contains('a-b-x\na-b-y\n'),
    );

    file('a/skills/a-b-y').deleteSync();
    await sync();

    expect(await check(), isEmpty);
  });

  test('check reports a skills directory that is a symlink', () async {
    Directory(path('b/skills')).renameSync(path('b/real_skills'));
    Link(path('b/skills')).createSync(path('b/real_skills'));

    expect(await check(), contains(startsWith('${path('b/skills')}:')));
  });

  test('sync refuses a skills directory that is a symlink', () async {
    Directory(path('b/skills')).renameSync(path('b/real_skills'));
    Link(path('b/skills')).createSync(path('b/real_skills'));

    await expectLater(sync, _throwsSkillsSyncException);

    expect(Directory(path('a/skills/a-b-x')).existsSync(), isFalse);
  });

  test('check reports a symlink under skills', () async {
    await sync();
    Link(path('b/skills/b-x/link')).createSync(path('b/skills/b-x/SKILL.md'));

    expect(await check(), [contains(path('b/skills/b-x/link'))]);
  });

  test('sync refuses a source that contains a symlink', () async {
    await sync();
    write('b/skills/b-x/references/new.md', 'new\n');
    Link(path('b/skills/b-x/link')).createSync(path('b/skills/b-x/SKILL.md'));

    await expectLater(sync, _throwsSkillsSyncException);

    expect(file('a/skills/a-b-x/references/r.md').existsSync(), isTrue);
    expect(file('a/skills/a-b-x/references/new.md').existsSync(), isFalse);
  });

  test('check skips a binary file when scanning for skill names', () async {
    File(path('b/skills/b-x/references/blob.bin'))
      ..createSync(recursive: true)
      ..writeAsBytesSync([0xff, 0xfe, 0x00]);
    await sync();

    expect(await check(), isEmpty);
  });

  test('sync refuses a GENERATED entry outside skills', () async {
    write('a/skills/GENERATED', '..\n');

    expect(sync, _throwsSkillsSyncException);
    expect(Directory(path('a')).existsSync(), isTrue);
  });

  test('check ignores Finder metadata in a copy', () async {
    await sync();
    write('a/skills/a-b-x/.DS_Store', 'x');

    expect(await check(), isEmpty);
  });

  test('check reports missing prefix', () async {
    await sync();
    write('b/skills/routing/SKILL.md', skillMd('routing'));

    expect(
      await check(),
      contains(
        allOf(contains(path('b/skills/routing')), contains('prefix b-')),
      ),
    );
  });

  test('check reports a name that differs from its directory', () async {
    write('b/skills/b-x/SKILL.md', skillMd('wrong'));
    await sync();

    expect(await check(), [contains(path('b/skills/b-x/SKILL.md'))]);
  });

  test('check reports cross-skill name', () async {
    write('b/skills/b-y/SKILL.md', skillMd('b-y'));
    write('b/skills/b-x/SKILL.md', '${skillMd('b-x')}See b-y.\n');
    await sync();

    expect(await check(), [
      allOf(contains(path('b/skills/b-x/SKILL.md')), contains('mentions b-y')),
    ]);
  });

  group('a package named only as a ship-map value', () {
    const ships = <String, List<String>>{
      'a': ['ext'],
    };

    late Directory ext;

    setUp(() {
      ext = externalPackage();
      writeConfig({'a': '../a', 'ext': Uri.directory(ext.path).toString()});
      writeIn(ext, 'skills/ext-x/SKILL.md', skillMd('ext-x'));
      writeIn(ext, 'skills/ext-x/references/r.md', 'ref\n');
    });

    test('is copied into a key and left untouched', () async {
      final before = snapshot(ext);

      final written = await runSync(repo.path, ships: ships);

      expect(written, [path('a/skills/a-ext-x')]);
      expect(
        file('a/skills/a-ext-x/references/r.md').readAsStringSync(),
        'ref\n',
      );
      expect(await runCheck(repo.path, ships: ships), isEmpty);
      expect(snapshot(ext), before);
    });

    test('copies only the skills its GENERATED does not list', () async {
      writeIn(ext, 'skills/ext-copy/SKILL.md', skillMd('ext-copy'));
      writeIn(ext, 'skills/GENERATED', '$_generatedHeader\next-copy\n');
      final before = snapshot(ext);

      await runSync(repo.path, ships: ships);

      expect(Directory(path('a/skills/a-ext-copy')).existsSync(), isFalse);
      expect(
        file('a/skills/GENERATED').readAsStringSync(),
        '$_generatedHeader\na-ext-x\n',
      );
      expect(await runCheck(repo.path, ships: ships), isEmpty);
      expect(snapshot(ext), before);
    });

    test('is refused when a copied skill contains a symlink', () async {
      Link(p.join(ext.path, 'skills', 'ext-x', 'link'))
          .createSync(p.join(ext.path, 'skills', 'ext-x', 'SKILL.md'));

      await expectLater(
        runSync(repo.path, ships: ships),
        _throwsSkillsSyncException,
      );
      expect(Directory(path('a/skills/a-ext-x')).existsSync(), isFalse);
      expect(
        await runCheck(repo.path, ships: ships),
        contains(contains(p.join(ext.path, 'skills', 'ext-x', 'link'))),
      );
    });

    test('is refused when its directory is missing', () async {
      ext.deleteSync(recursive: true);

      await expectLater(
        runSync(repo.path, ships: ships),
        throwsA(
          isA<SkillsSyncException>().having(
            (error) => error.message,
            'message',
            contains(ext.path),
          ),
        ),
      );
    });
  });

  test(
    'a key outside the repository is refused and nothing is written',
    () async {
      final outside = externalPackage();
      writeIn(outside, 'skills/a-old/SKILL.md', skillMd('a-old'));
      writeIn(outside, 'skills/GENERATED', '$_generatedHeader\na-old\n');
      writeConfig({'a': Uri.directory(outside.path).toString(), 'b': '../b'});
      final before = snapshot(outside);
      final refused = throwsA(
        isA<SkillsSyncException>().having(
          (error) => error.message,
          'message',
          allOf(contains(outside.path), contains('outside')),
        ),
      );

      await expectLater(sync, refused);
      await expectLater(check, refused);

      expect(snapshot(outside), before);
      expect(file('b/skills/GENERATED').existsSync(), isFalse);
      expect(Directory(path('b/skills')).listSync().length, 1);
    },
  );

  test(
    'targetSkillsDirectories lists the skills directory of each key',
    () async {
      expect(await targetSkillsDirectories(repo.path, ships: _ships), [
        path('a/skills'),
        path('b/skills'),
      ]);
    },
  );

  test(
    'resolvePackageRoots names the fix when the package config is missing',
    () async {
      file('.dart_tool/package_config.json').deleteSync();

      await expectLater(
        resolvePackageRoots(repo.path, ['a']),
        throwsA(
          isA<SkillsSyncException>().having(
            (error) => error.message,
            'message',
            allOf(
              contains(path('.dart_tool/package_config.json')),
              contains('dart pub get'),
              contains('melos bootstrap'),
            ),
          ),
        ),
      );
    },
  );

  group('runCli', () {
    final out = StringBuffer();
    final err = StringBuffer();

    setUp(() {
      out.clear();
      err.clear();
    });

    var lintPasses = true;
    List<String>? linted;

    setUp(() {
      lintPasses = true;
      linted = null;
    });

    Future<int> cli(List<String> args) => runCli(
      args,
      repoRoot: repo.path,
      ships: _ships,
      out: out,
      err: err,
      lint: (skillsDirectories) async {
        linted = skillsDirectories;
        return lintPasses;
      },
    );

    test('sync exits 0 and lists what it wrote', () async {
      expect(await cli(['sync']), 0);
      expect(out.toString(), contains(path('a/skills/a-b-x')));
    });

    test('check exits 1 with the problems and the fix command', () async {
      expect(await cli(['check']), 1);
      expect(out.toString(), contains(path('a/skills/a-b-x')));
      expect(out.toString(), contains('Run melos run skills:sync.'));
    });

    test('check exits 0 when clean', () async {
      await sync();

      expect(await cli(['check']), 0);
    });

    test('check lints the skills directory of every ship-map key', () async {
      await sync();

      await cli(['check']);

      expect(linted, [path('a/skills'), path('b/skills')]);
    });

    test('check exits 1 when the lint fails, without the sync hint', () async {
      await sync();
      lintPasses = false;

      expect(await cli(['check']), 1);
      expect(out.toString(), isNot(contains('melos run skills:sync')));
    });

    test('check still lints when a copy has drifted', () async {
      expect(await cli(['check']), 1);
      expect(linted, isNotNull);
    });

    test('sync does not lint', () async {
      await cli(['sync']);

      expect(linted, isNull);
    });

    test('exits 1 with the message on stderr when planning fails', () async {
      write('a/skills/a-b-x/SKILL.md', skillMd('a-b-x'));

      expect(await cli(['check']), 1);
      expect(err.toString(), contains('a-b-x'));
    });

    test(
      'exits 1 with the message on stderr without a package config',
      () async {
        file('.dart_tool/package_config.json').deleteSync();

        expect(await cli(['check']), 1);
        expect(err.toString(), contains('dart pub get'));
        expect(linted, isNull);
      },
    );

    test('exits 64 on an unknown command', () async {
      expect(await cli(['nope']), 64);
      expect(err.toString(), contains('Usage'));
    });
  });
}
